// Equal-date IDs use lexicographic (not numeric or locale) ordering.
const rows = [
  { id: 'b', tenant: 'a', createdAt: '2026-01-02', total: 1 },
  { id: '2', tenant: 'a', createdAt: '2026-01-01', total: 2 },
  { id: '11', tenant: 'other', createdAt: '2026-01-01', total: 3 },
  { id: '10', tenant: 'a', createdAt: '2026-01-01', total: 4 },
  { id: 'A', tenant: 'a', createdAt: '2026-01-01', total: 5 }
];
const snapshot = JSON.stringify(rows);
rows.forEach(Object.freeze);
Object.freeze(rows);
const paginated = new OrderHandler(new OrderRepository(rows));
let cursor;
const ids = [];
do {
  const page = paginated.list({ tenant: 'a', limit: 1, cursor });
  ids.push(...page.items.map(row => row.id));
  cursor = page.nextCursor;
} while (cursor !== null);
assert.deepEqual(ids, ['10', '2', 'A', 'b']);
assert.equal(JSON.stringify(rows), snapshot);
assert.deepEqual(paginated.list({ tenant: 'a', limit: 100 }).items.map(row => row.id), ids);
assert.equal(paginated.list({ tenant: 'a', limit: 100 }).nextCursor, null);
// The pair need not exist, and another tenant's pair is still a boundary.
for (const boundary of ['2026-01-01|11', '2026-01-01|15']) {
  assert.deepEqual(paginated.list({ tenant: 'a', limit: 2, cursor: boundary }), {
    items: [rows[1], rows[4]], nextCursor: '2026-01-01|A'
  });
}
assert.deepEqual(paginated.list({ tenant: 'a', limit: 1, cursor: '2026-01-02|b' }), {
  items: [], nextCursor: null
});
assert.deepEqual(paginated.list({ tenant: 'missing', limit: 1 }), { items: [], nextCursor: null });
for (const cursor of ['', '|', 'date|', '|id', 'date', 'date|id|extra', null, 1]) {
  assert.throws(() => paginated.list({ tenant: 'a', limit: 1, cursor }), /^Error: invalid request$/);
}
for (const limit of [0, -1, 101, 1.5, NaN, Infinity, '1']) {
  assert.throws(() => paginated.list({ tenant: 'a', limit }), /^Error: invalid request$/);
}
assert.throws(() => paginated.list({ tenant: '', limit: 1 }), /^Error: invalid request$/);

